<script>setInterval(async()=>{if(document.hidden)return;const label=document.getElementById('nx-refresh-state');try{const r=await fetch('/admin/dashboard?api=summary',{headers:{Accept:'application/json'}});if(!r.ok)throw Error();const data=await r.json();if(!data.ok)throw Error();for(const [key,value] of Object.entries(data.metrics))for(const node of document.querySelectorAll('[data-metric="'+key+'"]'))node.textContent=new Intl.NumberFormat('es-UY').format(value);label.textContent='Actualizado '+new Date().toLocaleTimeString('es-UY')}catch{label.textContent='Actualización interrumpida · recarga para continuar'}},30000);</script>
